from subprocess import run as execute
def launch(name):
    return execute(['python', '-m', name])

import subprocess as sp
def launch(name):
    return sp.run(['python', '-m', name])

from importlib import import_module as load
def fetch(name):
    return load(name)

import importlib as il
def fetch(name):
    return il.import_module(name)

from runpy import run_module as execute
def fetch(name):
    return execute(name)
